<script setup>
import AdminFilterSummary from '../../components/admin/AdminFilterSummary.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AppSkeleton from "../../components/common/AppSkeleton.vue"
import AdminIcon from '../../components/admin/AdminIcon.vue'
import AdminFilterExtras from '../../components/admin/AdminFilterExtras.vue'
import {reactive,watch} from 'vue'
import {RouterLink,useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../../stores/auth'
import {useApiState} from '../../composables/useApiState'
import {notificationsApi} from '../../api/notifications.api'
import {notificationStatuses,notificationChannels,notificationTypes,channelLabel,typeLabel} from '../../utils/notificationStatus'
import {formatDateTime} from '../../utils/formatters'
import NotificationBadge from '../../components/notifications/NotificationBadge.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),route=useRoute(),router=useRouter(),state=useApiState()
const filters=reactive({search:'',status:'',channel:'',type:'',provider:'',reference_uuid:'',date_from:'',date_to:'',sort:'created_at',direction:'desc'})
const filterDefaults={...filters}
let applied={},page=1
const {data,loading,error}=state
function load(){if(auth.can('notifications.view'))void state.run(signal=>notificationsApi.list({...applied,page,per_page:20},signal))}
function apply(next=1){if(next===1)applied={...filters};page=next;void router.replace({query:applied.reference_uuid?{reference_uuid:applied.reference_uuid}:{}});load()}
watch(()=>route.query.reference_uuid,value=>{filters.reference_uuid=typeof value==='string'?value:'';applied={...filters};page=1;state.clear();load()},{immediate:true})
watch(()=>auth.token,()=>{state.clear();load()})
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>الإشعارات</h1><p>سجل الرسائل الصادرة؛ كل إشعار قد يملك عدة محاولات إرسال.</p></div><button class="button" :disabled="loading" @click="load"><AdminIcon name="refresh"/> تحديث الإشعارات</button></AdminPageHeader><section class="panel notifications-panel"><form class="admin-list-filters" @submit.prevent="apply()"><div class="admin-filter-primary"><label class="field">بحث في المستلم<input v-model="filters.search" name="notification_search" type="search" maxlength="150"></label><label class="field">الحالة<select v-model="filters.status" name="notification_status"><option value="">كل الحالات</option><option v-for="(label,value) in notificationStatuses" :key="value" :value="value">{{ label }}</option></select></label><label class="field">القناة<select v-model="filters.channel" name="notification_channel"><option value="">كل القنوات المسجلة</option><option v-for="(label,value) in notificationChannels" :key="value" :value="value">{{ label }}</option></select></label><button class="button" :disabled="loading"><AdminIcon name="search"/> تطبيق الفلاتر</button></div><AdminFilterExtras :errors="error?.errors"><label class="field">نوع الإشعار<select v-model="filters.type" name="notification_type"><option value="">كل الأنواع</option><option v-for="(label,value) in notificationTypes" :key="value" :value="value">{{ label }}</option></select></label><label class="field">مزود الإرسال<input v-model="filters.provider" name="notification_provider" maxlength="50" pattern="[a-z0-9_-]+"></label><label class="field">من تاريخ<input v-model="filters.date_from" name="date_from" type="date"></label><label class="field">إلى تاريخ<input v-model="filters.date_to" name="date_to" type="date"></label><label class="field">ترتيب حسب<select v-model="filters.sort" name="notification_sort"><option value="created_at">وقت الإنشاء</option><option value="status">الحالة</option><option value="channel">القناة</option><option value="type">النوع</option></select></label><label class="field">الاتجاه<select v-model="filters.direction" name="direction"><option value="desc">الأحدث أولًا</option><option value="asc">الأقدم أولًا</option></select></label></AdminFilterExtras></form><AdminFilterSummary :filters="filters" :defaults="filterDefaults" :busy="loading" @clear="Object.assign(filters,filterDefaults);apply()"/><p v-if="filters.reference_uuid">تعرض الإشعارات المرتبطة بالمرجع المحدد. <button class="row-button" @click="filters.reference_uuid='';apply()">إلغاء قيد المرجع</button></p><AppSkeleton v-if="loading" variant="table" label="جارٍ تحميل الإشعارات…"/><div v-if="error" role="alert"><p>{{ error.message }}</p><p v-for="(messages,key) in error.errors" :key="key">{{ messages.join(' ') }}</p><button class="button" :disabled="loading" @click="load">إعادة المحاولة</button></div><div v-if="data" class="table-wrap"><table v-admin-table class="notifications-table"><thead><tr><th>الإشعار والقناة</th><th>المستلم</th><th>الحالة</th><th>المحاولات</th><th>الأوقات</th><th></th></tr></thead><tbody><tr v-for="notification in data.data" :key="notification.id"><td><div class="admin-cell-value">{{ typeLabel(notification.type) }}<small>{{ channelLabel(notification.channel) }}</small></div></td><td><div class="admin-cell-value"><span dir="ltr">{{ notification.recipient }}</span></div></td><td><div class="admin-cell-value"><NotificationBadge :status="notification.status"/></div></td><td><div class="admin-cell-value">{{ notification.attempts }} / {{ notification.max_attempts }}</div></td><td><div class="admin-cell-value">{{ formatDateTime(notification.created_at) }}<small v-if="notification.sent_at">إرسال: {{ formatDateTime(notification.sent_at) }}</small><small v-if="notification.failed_at">تعذر: {{ formatDateTime(notification.failed_at) }}</small></div></td><td><div class="admin-cell-value"><RouterLink class="row-button" :to="'/admin/notifications/'+notification.id">التفاصيل والمحاولات <AdminIcon name="arrow-left"/></RouterLink></div></td></tr></tbody></table></div><p v-if="data&&!data.data.length" class="empty">لا توجد إشعارات تطابق الفلاتر.</p><ApiPagination v-if="data" :meta="data.meta" :links="data.links" :busy="loading" @page="apply"/></section></main></template>

